<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import ManagementLayout from '@/components/ManagementLayout.vue'
import { platformApi, type Classroom, type Device, type SchoolClass } from '@/api/platform'
const devices = ref<Device[]>([]); const classrooms = ref<Classroom[]>([]); const classes = ref<SchoolClass[]>([]); const loading = ref(true); const error = ref(''); const mode = ref<'room'|'device'|'binding'|''>(''); const saving = ref(false); const roomForm = ref({name:'',location:''}); const deviceForm = ref({deviceCode:'',name:'',type:'classroom_screen'}); const bindingForm = ref({deviceId:'',classroomId:'',classId:''})
async function load(){loading.value=true;error.value='';try{const [d,c,k]=await Promise.all([platformApi.devices(),platformApi.classrooms(),platformApi.classes()]);devices.value=d.data;classrooms.value=c.data;classes.value=k.data.items}catch{error.value='教室、设备或班级加载失败，请检查登录状态后重试。'}finally{loading.value=false}}
async function createRoom(){if(!roomForm.value.name.trim())return;saving.value=true;try{await platformApi.createClassroom({name:roomForm.value.name.trim(),location:roomForm.value.location.trim()||undefined});roomForm.value={name:'',location:''};mode.value='';ElMessage.success('教室添加成功');await load()}catch{ElMessage.error('教室添加失败')}finally{saving.value=false}}
async function createDevice(){if(!deviceForm.value.deviceCode.trim()||!deviceForm.value.name.trim())return;saving.value=true;try{await platformApi.createDevice(deviceForm.value);deviceForm.value={deviceCode:'',name:'',type:'classroom_screen'};mode.value='';ElMessage.success('设备添加成功');await load()}catch{ElMessage.error('设备添加失败，请检查设备编码是否重复。')}finally{saving.value=false}}
async function bindDevice(){if(!bindingForm.value.deviceId||!bindingForm.value.classroomId||!bindingForm.value.classId)return;saving.value=true;try{await platformApi.bindDevice({deviceId:Number(bindingForm.value.deviceId),classroomId:Number(bindingForm.value.classroomId),classId:Number(bindingForm.value.classId)});bindingForm.value={deviceId:'',classroomId:'',classId:''};mode.value='';ElMessage.success('设备绑定成功')}catch{ElMessage.error('设备绑定失败，请检查设备是否已有其他绑定。')}finally{saving.value=false}}
function status(v:string){return v==='online'?'在线':v==='fault'?'故障':v==='disabled'?'停用':'离线'}
onMounted(load)
</script>
<template><ManagementLayout><div class="page"><header><div><h1>教室与设备</h1><p>维护教室、大屏设备及其在线状态。</p></div><div class="toolbar"><button class="button" @click="load">刷新</button><button class="button" @click="mode=mode==='room'?'':'room'">{{mode==='room'?'取消':'添加教室'}}</button><button class="button" @click="mode=mode==='device'?'':'device'">{{mode==='device'?'取消':'添加设备'}}</button><button class="button" @click="mode=mode==='binding'?'':'binding'">{{mode==='binding'?'取消':'绑定设备'}}</button></div></header><div v-if="mode==='room'" class="panel form"><label>教室名称<input v-model="roomForm.name" placeholder="如：一号教室"/></label><label>位置<input v-model="roomForm.location" placeholder="如：一楼东侧"/></label><button class="button" :disabled="saving||!roomForm.name.trim()" @click="createRoom">保存教室</button></div><div v-if="mode==='device'" class="panel form"><label>设备编码<input v-model="deviceForm.deviceCode" placeholder="设备唯一编码"/></label><label>设备名称<input v-model="deviceForm.name" placeholder="如：一号教室大屏"/></label><label>设备类型<select v-model="deviceForm.type"><option value="classroom_screen">教室大屏</option><option value="teacher_tablet">教师平板</option><option value="teacher_phone">教师手机</option></select></label><button class="button" :disabled="saving||!deviceForm.deviceCode.trim()||!deviceForm.name.trim()" @click="createDevice">保存设备</button></div><div v-if="mode==='binding'" class="panel form"><label>设备<select v-model="bindingForm.deviceId"><option value="">请选择设备</option><option v-for="x in devices" :key="x.id" :value="String(x.id)">{{x.name}}</option></select></label><label>教室<select v-model="bindingForm.classroomId"><option value="">请选择教室</option><option v-for="x in classrooms" :key="x.id" :value="String(x.id)">{{x.name}}</option></select></label><label>班级<select v-model="bindingForm.classId"><option value="">请选择班级</option><option v-for="x in classes" :key="x.id" :value="String(x.id)">{{x.name}}</option></select></label><button class="button" :disabled="saving||!bindingForm.deviceId||!bindingForm.classroomId||!bindingForm.classId" @click="bindDevice">保存绑定</button></div><div class="summary"><span>教室 {{classrooms.length}}</span><span>设备 {{devices.length}}</span></div><div v-if="loading" class="panel">正在加载教室和设备…</div><div v-else-if="error" class="panel bad">{{error}} <button class="link" @click="load">重试</button></div><template v-else><div class="panel"><h2>教室</h2><p v-if="!classrooms.length" class="muted">暂无教室，请先添加。</p><table v-else class="table"><thead><tr><th>名称</th><th>位置</th><th>状态</th></tr></thead><tbody><tr v-for="x in classrooms" :key="x.id"><td>{{x.name}}</td><td>{{x.location||'—'}}</td><td>{{x.status==='active'?'启用':'停用'}}</td></tr></tbody></table></div><div class="panel"><h2>设备</h2><p v-if="!devices.length" class="muted">暂无设备，请先添加。</p><table v-else class="table"><thead><tr><th>设备</th><th>编码</th><th>类型</th><th>状态</th><th>最近在线</th></tr></thead><tbody><tr v-for="x in devices" :key="x.id"><td>{{x.name}}</td><td>{{x.deviceCode}}</td><td>{{x.type}}</td><td>{{status(x.status)}}</td><td>{{x.lastOnlineAt||'暂无记录'}}</td></tr></tbody></table></div></template></div></ManagementLayout></template>
<style scoped>.page{max-width:1180px;margin:auto}.page header{display:flex;justify-content:space-between;align-items:flex-end;gap:18px}.page h1{margin:0 0 8px;color:#60483e;font-size:40px}.page p{margin:0;color:#9a7e6e}.toolbar{display:flex;gap:10px}.button{border:0;border-radius:12px;padding:0 18px;min-height:42px;background:#e99168;color:#fff;font:inherit;cursor:pointer}.button:disabled{opacity:.55}.panel{margin-top:20px;padding:20px;border:1px solid #f0ddce;border-radius:18px;background:#fffdf9;box-shadow:0 10px 28px #b9795114}.form{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.form label{display:grid;gap:6px;color:#876b5d;font-size:13px}.form input,.form select{height:40px;min-width:180px;border:1px solid #efd9c8;border-radius:10px;padding:0 10px;background:#fffdf9}.summary{display:flex;gap:14px;margin-top:18px}.summary span{padding:10px 15px;border-radius:12px;background:#fff0e4;color:#a9654c}.table{width:100%;border-collapse:collapse;color:#60483e}.table th,.table td{text-align:left;padding:13px 10px;border-bottom:1px solid #f4e6dc}.link{border:0;background:none;color:#d67b59;cursor:pointer}.bad{color:#c64e4e}.muted{color:#9a7e6e}.panel h2{margin:0 0 12px;color:#60483e}@media(max-width:850px){.page header{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.table{display:block;overflow:auto;white-space:nowrap;font-size:13px}}</style>
